/bin/zsh -lc "python3 -c 'from pathlib import Path
s = Path(\"material.md\").read_text()
print(\"连续双反斜杠出现次数：\", s.count(chr(92) * 2))
roads = [(1, 2, 1), (2, 3, 1), (3, 1, 1)]
for label, two_way in [(\"全部按 u 到 v 单向\", False), (\"前两条单向，第三条双向\", True)]:
    d = [[0 if i == j else 10**9 for j in range(3)] for i in range(3)]
    for k, (u, v, w) in enumerate(roads):
        d[u-1][v-1] = w
        if k == 2 and two_way:
            d[v-1][u-1] = w
    for k in range(3):
        for i in range(3):
            for j in range(3):
                d[i][j] = min(d[i][j], d[i][k] + d[k][j])
    print(label)
    print(\"任意两城互相可达：\", all(x < 10**9 for row in d for x in row))
    print(\"原样例 1 到 2 的答案：\", d[0][1])
    print(\"查询改为 1 到 3 的答案：\", d[0][2])
'"

